83	// hostFromPublicURL extracts the bare cluster host from a cluster's public_url
84	// (with or without a scheme) and runs it through validateClusterHost, the same
85	// anti-token-leak guard the positional <cluster-host> arg uses. Kept separate
86	// so the ListClusters → regionChoice mapping is unit-testable without a live
87	// catalog.
88	func hostFromPublicURL(raw string) (string, error) {
89		s := strings.TrimSpace(raw)
90		if s == "" {
91			return "", errors.New("empty public_url")
92		}
93		if !strings.Contains(s, "://") {
94			s = "https://" + s
95		}
96		u, err := url.Parse(s)
97		if err != nil {
98			return "", fmt.Errorf("parse public_url %q: %w", raw, err)
99		}
100		if u.Host == "" {
101			return "", fmt.Errorf("public_url %q has no host", raw)
102		}
103		// Reject anything beyond scheme://host[:port]. url.Parse demotes the
104		// `host@evil.com` userinfo trick into u.User (leaving u.Host=evil.com) and
105		// stashes a trailing path in u.Path, neither of which validateClusterHost
106		// would otherwise see. A bare "/" path is tolerated: publicUrl is a trusted
107		// catalog field, and a trailing slash (https://host/) is benign — rejecting
108		// it would silently drop the cluster and could leave the wizard with no
109		// regions. Anything richer (a real path, query, fragment, userinfo) is still
110		// refused, since the host flows into clone URLs and the STS audience.
111		if u.User != nil || (u.Path != "" && u.Path != "/") || u.RawQuery != "" || u.Fragment != "" {
112			return "", fmt.Errorf("public_url %q must be scheme://host[:port] only", raw)
113		}
114		if err := validateClusterHost(u.Host); err != nil {
115			return "", err
116		}
117		return u.Host, nil
118	}
